      now.getMinutes()
    ).padStart(2, '0')}`;

    const newNotification: OutageNotification = {
      ...notifData,
      id: `NOTIF-2026-${String(notifications.length + 1).padStart(3, '0')}`,
      timestamp,
      status: 'Simulated Sent',
    };

    setNotifications((prev) => [newNotification, ...prev]);

    showToast(
      'Notification Broadcasted',
